import httpx,json
schema={'type':'object','properties':{'captions':{'type':'array','items':{'type':'object','properties':{'id':{'type':'string'},'text':{'type':'string','pattern':'^[ -~]*$'}},'required':['id','text'],'additionalProperties':False}}},'required':['captions'],'additionalProperties':False}
prompt='You write spoken TELUGU in ordinary English letters. ALL text must be TELUGU words written in Latin letters. Never Telugu script, Hindi, or English translation. Preserve questions, tense, negation and meaning. For English input, translate meaning into natural spoken Telugu first and then write it in English letters. Examples: Are you coming to college today? => Nuvvu eeroju college ki vasthunnava?; Yes bro. => Avunu bro.; I will be there in 10 minutes. => Nenu 10 nimishallo akkada unta.; నువ్వు ఈరోజు కాలేజీకి వస్తున్నావా? => Nuvvu eeroju college ki vasthunnava?; అతను రాలేదు. => Athanu raledu. Return JSON captions [{id,text}] with exactly the input ids and order. /no_think'
for texts in [['Are you coming to college today?','Yes bro.','I will be there in 10 minutes.'],['నువ్వు ఈరోజు కాలేజీకి వస్తున్నావా?','అతను రాలేదు.','ఏంటి బ్రో నువ్వు ఇంకా రాలేదు?']]:
 r=httpx.post('http://127.0.0.1:8766/v1/chat/completions',json={'messages':[{'role':'system','content':prompt},{'role':'user','content':json.dumps({'captions':[{'id':str(i),'text':t} for i,t in enumerate(texts)]},ensure_ascii=False)}],'temperature':0.25,'max_tokens':800,'response_format':{'type':'json_schema','json_schema':{'name':'captions','schema':schema}}},timeout=180)
 print(r.status_code,r.json().get('choices',[{}])[0].get('message',r.text),flush=True)
